        61:"🤨",62:"😴",63:"👏🏻",64:"🐲",65:"⭐",66:"🌧️",67:"🍉",68:"🍵",69:"🔥",70:"💯"
    };

    function removeFnEmoji(s) {
        return s ? s.replace(/\[fn=\d+\]/g, '') : '';
    }

    function replaceFnEmoji(s) {
        return s ? s.replace(/\[fn=(\d+)\]/g, function(match, id) {
            return EMOJI[parseInt(id)] || '';
        }) : '';
    }

    let commentListArray = [];
    if (commentList && typeof commentList == 'object' && commentList.length !== undefined) {
        commentListArray = commentList;
    } else if (Array.isArray(commentList)) {
