<div id="result-output" style="display:none;">` + savedParams + `</div>
<script>
var config = ` + JSON.stringify(config) + `;
var selection = { length: null, status: null, sort: null };

var initParams = document.getElementById('result-output').textContent.trim();
if (initParams && initParams !== "未选择" && initParams !== "undefined") {
    initParams.split(", ").forEach(function(item) {
        if (config.lengths.indexOf(item) >= 0) selection.length = item;
        else if (config.statuses.indexOf(item) >= 0) selection.status = item;
        else if (config.sorts.indexOf(item) >= 0) selection.sort = item;
    });
}

document.querySelectorAll('.opt-card').forEach(function(el) {
    var cat = el.getAttribute('data-cat');
    var val = el.getAttribute('data-val');
    if (selection[cat] == val) el.classList.add('selected');
});

function pick(el) {
    var cat = el.getAttribute('data-cat');
    var val = el.getAttribute('data-val');
    if (selection[cat] == val) {
        selection[cat] = null;
        el.classList.remove('selected');
    } else {
        selection[cat] = val;
        document.querySelectorAll('.opt-card[data-cat="' + cat + '"]').forEach(function(c) {
            c.classList.remove('selected');
        });
        el.classList.add('selected');
    }
    updateOutput();
}

function updateOutput() {
    var all = [];
    for (var k in selection) { if (selection[k]) all.push(selection[k]); }
    var text = all.length > 0 ? all.join(", ") : "未选择";
    document.getElementById('current-value').textContent = text;
    document.getElementById('result-output').textContent = all.length > 0 ? all.join(", ") : "";
