        var typeLabels = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeIcons = {
            novel: 'fa-solid fa-book-open',
            audio: 'fa-solid fa-headphones',
            comic: 'fa-solid fa-images',
            video: 'fa-solid fa-clapperboard'
        };
        var typeKeywords = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeOrder = ['novel', 'audio', 'comic', 'video'];

        try {
            var apiUrl = getServerHost() + '/api/get_config';
            var resp = JSON.parse(java.ajax(apiUrl));
            if (resp && Array.isArray(resp)) {
                resp.forEach(function (item) {
                    if (!item.name || !item.key) return;
                    var t = item.type || 'novel';
                    if (!typeToItems[t]) typeToItems[t] = [];
                    typeToItems[t].push({
                        name: item.name,
                        key: item.key,
                        free: item.free || ''
                    });
                });
            }
        } catch (e) {
            java.toast("获取源站列表失败，请切换服务器后重试");
            return;
        }

        var currentRaw = config.source || '';
        var currentIsAll = false;
        var currentAllType = '';
        for (var k in typeKeywords) {
            if (typeKeywords[k] == currentRaw) {
                currentIsAll = true;
                currentAllType = k;
                break;
            }
        }
        var selectedNames = [];
        if (currentRaw && !currentIsAll) {
            selectedNames = currentRaw.split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s; });
        }
        var selectedSet = {};
        selectedNames.forEach(function (n) { selectedSet[n] = true; });

        var firstType = 'novel';
        if (currentIsAll) {
            firstType = currentAllType;
        } else if (selectedNames.length > 0) {
            for (var t in typeToItems) {
                for (var i = 0; i < typeToItems[t].length; i++) {
                    if (typeToItems[t][i].name == selectedNames[0]) { firstType = t; break; }
                }
                if (firstType == t) break;
            }
        }

        var currentGender = config.gender || 'boy';

        var tabBtnsHtml = '';
        var panelsHtml = '';

        typeOrder.forEach(function (t) {
            var items = typeToItems[t] || [];
            var active = (t == firstType) ? ' active' : '';
            var count = items.length;

            tabBtnsHtml += '<button class="tab-btn' + active + '" data-tab="' + t + '" onclick="switchTab(\'' + t + '\')">'
                         + '<i class="' + typeIcons[t] + '"></i>'
                         + '<span>' + typeLabels[t] + '</span>'
                         + '<em>' + count + '</em>'
                         + '</button>';

            var panel = '<div class="panel' + active + '" id="panel-' + t + '">';
            panel += '<div class="grid">';

            var allSel = (currentIsAll && currentAllType == t) ? ' selected' : '';
            panel += '<div class="src-card all-card' + allSel + '"'
                   + ' data-type="' + t + '" data-name="" data-all="1"'
                   + ' onclick="pick(this)">'
                   + '<span class="src-name"><i class="fa-solid fa-star card-ico"></i>全部</span>'
                   + '</div>';

            items.forEach(function (it) {
                var sel = selectedSet[it.name] ? ' selected' : '';
                var vip = (it.free == 'svip') ? '<span class="vip-tag">VIP</span>' : '';
                panel += '<div class="src-card' + sel + '" data-type="' + t
                       + '" data-name="' + it.name + '" data-all="0"'
                       + ' onclick="pick(this)">'
                       + '<span class="src-name">' + it.name + '</span>'
                       + vip
                       + '</div>';
            });

            panel += '</div></div>';
            panelsHtml += panel;
        });

        var initDisplay = '未选择';
        if (currentIsAll) {
            initDisplay = typeLabels[currentAllType] + ' · 全部';
        } else if (selectedNames.length > 0) {
            initDisplay = selectedNames.join('、');
        }
        var initCount = currentIsAll ? 'ALL' : selectedNames.length;

        var boyActive = (currentGender == 'boy') ? ' active' : '';
        var girlActive = (currentGender == 'girl') ? ' active' : '';

        var host = getServerHost();
        var html = `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0,user-scalable=no">
<title>源站多选</title>
<link rel="stylesheet" href="https://cdn.bootcdn.net/ajax/libs/font-awesome/6.5.2/css/all.min.css">
<style>
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}

:root{
    --rose:#e07a8b;
    --rose-dark:#c25a72;
    --rose-soft:#f7a8b8;
    --gold:#c9a55c;
    --gold-dark:#a8802e;
    --ink-1:#4a3a44;
    --ink-2:#6b5765;
    --ink-3:#9b8b98;
    --line:rgba(190,150,170,.2);
}

html,body{height:100%}

body{
    font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Microsoft YaHei',sans-serif;
    color:var(--ink-1);
    min-height:100vh;
    padding:18px 14px 32px;
    position:relative;
    overflow-x:hidden;
    background:#fdf6f8;
}

.bg-layer{
    position:fixed;inset:0;z-index:0;pointer-events:none;
    background:
        radial-gradient(680px 420px at 8% -6%, rgba(255,205,220,.85), transparent 60%),
        radial-gradient(720px 460px at 98% 4%, rgba(255,224,190,.7), transparent 62%),
        radial-gradient(700px 500px at 50% 108%, rgba(214,182,255,.35), transparent 60%),
        linear-gradient(180deg,#fff8fa 0%,#fdf3f6 45%,#f9edf2 100%);
}

#bubbles{
    position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden;
}

.bubble{
    position:absolute;
    bottom:-120px;
    border-radius:50%;
    background:radial-gradient(circle at 30% 30%, rgba(255,255,255,.95), rgba(255,255,255,.15) 60%, rgba(255,220,230,.35) 100%);
    box-shadow:
        0 0 12px rgba(255,220,230,.6),
        0 0 24px rgba(240,180,200,.25),
        inset -3px -5px 8px rgba(240,180,200,.25),
        inset 4px 6px 10px rgba(255,255,255,.9);
    animation:rise linear infinite;
    will-change:transform,opacity;
}

@keyframes rise{
    0%{transform:translate3d(0,0,0) scale(.6);opacity:0;}
    10%{opacity:.9;}
    35%{transform:translate3d(var(--drift),-38vh,0) scale(1);}
    65%{transform:translate3d(calc(var(--drift) * -0.7), -68vh, 0) scale(1.05);}
    90%{opacity:.7;}
    100%{transform:translate3d(var(--drift),-115vh,0) scale(1.1);opacity:0;}
}

.wrap{
    position:relative;z-index:2;
    width:100%;max-width:640px;margin:0 auto;
    background:rgba(255,250,252,.72);
    backdrop-filter:blur(28px) saturate(160%);
    -webkit-backdrop-filter:blur(28px) saturate(160%);
    border-radius:28px;
    border:1px solid rgba(255,255,255,.9);
    box-shadow:
        0 30px 60px -28px rgba(200,120,150,.45),
        0 12px 30px -18px rgba(180,140,180,.35),
        0 1px 0 rgba(255,255,255,.9) inset;
    overflow:hidden;
    animation:riseIn .7s cubic-bezier(.22,.61,.36,1);
}
@keyframes riseIn{from{opacity:0;transform:translateY(20px) scale(.985)}to{opacity:1;transform:none}}

.head{
    position:relative;
    padding:28px 24px 20px;
    text-align:center;
    background:
        radial-gradient(120% 150% at 50% -30%, rgba(255,214,224,.85), transparent 65%),
        linear-gradient(180deg, rgba(255,255,255,.6), transparent);
}
.head::after{
    content:'';
    position:absolute;left:50%;bottom:0;
    width:180px;height:1px;transform:translateX(-50%);
    background:linear-gradient(90deg,transparent,var(--line) 30%,var(--line) 70%,transparent);
}

.head-orn{
    display:flex;align-items:center;justify-content:center;gap:10px;
    margin-bottom:10px;
    color:var(--rose);
    font-size:11px;
    letter-spacing:6px;
    opacity:.7;
}
.head-orn::before,.head-orn::after{
    content:'';
    width:36px;height:1px;
    background:linear-gradient(90deg,transparent,var(--rose-soft));
}
.head-orn::after{background:linear-gradient(270deg,transparent,var(--rose-soft))}

.head h1{
    font-size:22px;
    font-weight:700;
    letter-spacing:3px;
    background:linear-gradient(100deg,#c25a72 15%,#e07a8b 45%,#c9a55c 90%);
    -webkit-background-clip:text;
    background-clip:text;
    -webkit-text-fill-color:transparent;
    filter:drop-shadow(0 1px 0 rgba(255,255,255,.9));
}

.save-tip{
    display:flex;align-items:flex-start;gap:9px;
    margin:14px 4px 0;
    padding:10px 14px;
    border-radius:12px;
    font-size:11.5px;
    line-height:1.55;
    text-align:left;
    color:var(--rose-dark);
    background:linear-gradient(135deg, rgba(255,240,244,.95), rgba(255,222,232,.75));
    border:1px solid rgba(240,180,200,.5);
    box-shadow:0 6px 14px -8px rgba(200,120,150,.5), 0 1px 0 rgba(255,255,255,.9) inset;
}
.save-tip i{
    font-size:13px;
    color:var(--rose);
    flex:none;
    margin-top:1px;
}
.save-tip span{flex:1}

.gender-wrap{
    margin:16px 22px 0;
    display:flex;gap:8px;
    padding:5px;
    border-radius:16px;
    background:linear-gradient(135deg, rgba(255,255,255,.7), rgba(255,236,240,.45));
    border:1px solid rgba(255,255,255,.9);
    box-shadow:0 6px 18px -14px rgba(200,120,150,.6), 0 1px 0 rgba(255,255,255,.9) inset;
}
.gender-btn{
    flex:1;
    display:flex;align-items:center;justify-content:center;gap:7px;
    padding:10px 6px;
    border-radius:12px;
    border:1px solid transparent;
    background:transparent;
    cursor:pointer;
    color:var(--ink-3);
    font-family:inherit;
    font-size:12px;
    font-weight:600;
    letter-spacing:.5px;
    transition:all .28s cubic-bezier(.4,0,.2,1);
}
.gender-btn i{font-size:13px;transition:all .28s}
.gender-btn:hover{color:var(--rose);background:rgba(255,240,244,.65)}
.gender-btn.active{
    color:#fff;
    background:linear-gradient(145deg,#e07a8b,#c25a72);
    box-shadow:
        0 10px 22px -10px rgba(194,90,114,.75),
        0 1px 0 rgba(255,255,255,.4) inset;
}
.gender-btn.active i{transform:scale(1.1)}
.gender-btn.girl.active{
    background:linear-gradient(145deg,#c78fd0,#a26bb0);
    box-shadow:
        0 10px 22px -10px rgba(162,107,176,.75),
        0 1px 0 rgba(255,255,255,.4) inset;
}

.badge-wrap{
    margin:14px 22px 0;
    display:flex;align-items:center;gap:10px;
    padding:11px 15px;
    border-radius:16px;
    background:linear-gradient(135deg, rgba(255,255,255,.75), rgba(255,236,240,.55));
    border:1px solid rgba(255,255,255,.9);
    box-shadow:
        0 8px 22px -14px rgba(200,120,150,.55),
        0 1px 0 rgba(255,255,255,.9) inset;
}
.badge-dot{
    width:7px;height:7px;flex:none;border-radius:50%;
    background:var(--rose);
    box-shadow:0 0 0 3px rgba(224,122,139,.18), 0 0 10px rgba(224,122,139,.6);
    animation:beat 1.8s ease-in-out infinite;
}
@keyframes beat{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.3);opacity:.65}}

.badge-lbl{font-size:11px;color:var(--ink-3);letter-spacing:1px;flex:none}
.badge-val{
    flex:1;text-align:right;
    font-size:12.5px;font-weight:700;
    color:var(--rose-dark);
    white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
}
.cnt-pill{
    flex:none;
    font-size:9.5px;font-weight:800;
    padding:2.5px 9px;border-radius:999px;
    color:#fff;
    letter-spacing:.4px;
    background:linear-gradient(135deg,#e07a8b,#c25a72);
    box-shadow:0 3px 10px -4px rgba(194,90,114,.8);
}

.tabs{
    display:flex;gap:5px;
    margin:12px 22px 0;
    padding:5px;
    border-radius:16px;
    background:linear-gradient(135deg, rgba(255,255,255,.7), rgba(255,236,240,.45));
    border:1px solid rgba(255,255,255,.9);
    box-shadow:0 6px 18px -14px rgba(200,120,150,.6), 0 1px 0 rgba(255,255,255,.9) inset;
}
.tab-btn{
    flex:1;
    position:relative;
    display:flex;flex-direction:column;align-items:center;gap:3px;
    padding:9px 4px;
    border-radius:12px;
    border:none;
    background:transparent;
    cursor:pointer;
    color:var(--ink-3);
    font-family:inherit;
    transition:all .28s cubic-bezier(.4,0,.2,1);
}
.tab-btn i{font-size:14px;transition:all .28s}
.tab-btn span{font-size:10.5px;font-weight:600;letter-spacing:.3px}
.tab-btn em{
    position:absolute;top:3px;right:6px;
    font-style:normal;font-size:9px;font-weight:800;
    padding:1px 5px;border-radius:999px;
    background:rgba(224,122,139,.12);
    color:var(--rose);
    transition:all .25s;
}
.tab-btn:hover{color:var(--rose);background:rgba(255,240,244,.65)}
.tab-btn.active{
    color:#fff;
    background:linear-gradient(145deg,#e07a8b,#c25a72);
    box-shadow:
        0 10px 22px -10px rgba(194,90,114,.75),
        0 1px 0 rgba(255,255,255,.4) inset;
}
.tab-btn.active i{transform:scale(1.1)}
.tab-btn.active em{background:rgba(255,255,255,.28);color:#fff}

.panel{display:none;padding:16px 22px 0}
.panel.active{display:block;animation:softIn .4s cubic-bezier(.22,.61,.36,1)}
@keyframes softIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}

.src-card{
    position:relative;
    padding:15px 8px;
    border-radius:14px;
    background:linear-gradient(160deg, rgba(255,255,255,.85), rgba(255,244,247,.55));
    border:1px solid rgba(255,255,255,.95);
    cursor:pointer;
    text-align:center;
    user-select:none;
    transition:all .25s cubic-bezier(.4,0,.2,1);
    box-shadow:
        0 6px 14px -12px rgba(180,120,150,.55),
        0 1px 0 rgba(255,255,255,.9) inset;
}
.src-card:hover{
    transform:translateY(-2px);
    background:linear-gradient(160deg,#fff,#fff2f6);
    border-color:rgba(247,168,184,.6);
    box-shadow:
        0 12px 24px -14px rgba(200,120,150,.55),
        0 0 0 1px rgba(247,168,184,.25),
        0 1px 0 rgba(255,255,255,.95) inset;
}
.src-card:active{transform:translateY(-1px) scale(.98)}

.src-name{
    position:relative;z-index:1;
    font-size:12.5px;font-weight:600;
    color:var(--ink-2);
    line-height:1.3;
    word-break:break-all;
    transition:color .2s;
    display:inline-flex;align-items:center;gap:4px;
}

.src-card.selected{
    background:linear-gradient(145deg,#ffe4ea,#f7c8d3);
    border-color:rgba(224,122,139,.9);
    box-shadow:
        0 14px 26px -14px rgba(194,90,114,.7),
        0 0 0 1px rgba(224,122,139,.35) inset;
}
.src-card.selected .src-name{color:var(--rose-dark);font-weight:700}

.all-card{
    background:linear-gradient(160deg, #fff7ea, #fdeccb);
    border-color:rgba(243,207,139,.65);
}
.all-card .card-ico{
    font-size:11px;
    color:var(--gold);
    transition:all .3s;
}
.all-card:hover{
    border-color:rgba(201,165,92,.9);
    background:linear-gradient(160deg,#fff9f0,#fbe4b8);
}
.all-card.selected{
    background:linear-gradient(145deg,#fde7b8,#f3c97a);
    border-color:rgba(201,165,92,.9);
    box-shadow:
        0 14px 26px -14px rgba(180,140,70,.7),
        0 0 0 1px rgba(201,165,92,.35) inset;
}
.all-card.selected .src-name{color:#7a5a1c}
.all-card.selected .card-ico{
    color:#7a5a1c;
    transform:rotate(72deg) scale(1.15);
}

.vip-tag{
    position:absolute;bottom:5px;right:6px;
    display:inline-flex;align-items:center;justify-content:center;
    font-size:8px;font-weight:800;
    padding:1px 5px;
    border-radius:6px;
    color:#8a6420;
    background:rgba(243,207,139,.55);
    border:1px solid rgba(201,165,92,.55);
    letter-spacing:.3px;
    line-height:1.2;
}

.foot{padding:20px 22px 24px}

.clear-btn{
    display:flex;align-items:center;justify-content:center;gap:8px;
    width:100%;
    padding:12px;
    border-radius:14px;
    border:1px dashed rgba(224,122,139,.45);
    background:linear-gradient(135deg, rgba(255,255,255,.7), rgba(255,236,240,.4));
    color:var(--rose);
    font-family:inherit;
    font-size:12.5px;
    font-weight:600;
    letter-spacing:1px;
    cursor:pointer;
    transition:all .28s;
    box-shadow:0 1px 0 rgba(255,255,255,.9) inset;
}
.clear-btn i{font-size:12px;transition:transform .4s}
.clear-btn:hover{
    border-color:rgba(224,122,139,.9);
    background:linear-gradient(135deg,#fff,#ffeef2);
    color:var(--rose-dark);
}
.clear-btn:hover i{transform:rotate(-180deg)}
.clear-btn:active{transform:scale(.985)}

@media (max-width:400px){
    .grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:7px}
    .src-card{padding:13px 5px;border-radius:12px}
    .src-name{font-size:11px}
    .head h1{font-size:20px}
    .tab-btn span{font-size:9.5px}
    .tab-btn i{font-size:13px}
    .gender-wrap{margin:14px 16px 0}
    .badge-wrap{margin:12px 16px 0}
    .tabs{margin:10px 16px 0}
    .panel{padding:14px 16px 0}
    .foot{padding:18px 16px 22px}
}
</style>
</head>
<body>

<div class="bg-layer"></div>
<div id="bubbles"></div>

<div class="wrap">

    <div class="head">
        <div class="head-orn">SOURCE</div>
        <h1>源站选择</h1>
        <div class="save-tip">
            <i class="fa-solid fa-circle-info"></i>
            <span>可跨分类多选；选「全部」即该分类全部源站，与具体源站互斥。多选时发现页仅展示第一个源站。选好后点右上角 ✓ 保存。</span>
        </div>
    </div>

    <div class="gender-wrap">
        <button class="gender-btn boy` + boyActive + `" data-gender="boy" onclick="pickGender('boy')">
            <i class="fa-solid fa-mars"></i>男频
        </button>
        <button class="gender-btn girl` + girlActive + `" data-gender="girl" onclick="pickGender('girl')">
            <i class="fa-solid fa-venus"></i>女频
        </button>
    </div>

    <div class="badge-wrap">
        <span class="badge-dot"></span>
        <span class="badge-lbl">已选</span>
        <span id="current-value" class="badge-val">` + initDisplay + `</span>
        <span id="current-count" class="cnt-pill">` + initCount + `</span>
    </div>

    <div class="tabs">` + tabBtnsHtml + `</div>

    <div>` + panelsHtml + `</div>

    <div class="foot">
        <button class="clear-btn" onclick="clearAll()">
            <i class="fa-regular fa-trash-can"></i>
            清空所有选择
        </button>
    </div>

</div>

<div id="result-output" style="display:none;">` + (currentIsAll ? ('__ALL__' + currentAllType) : selectedNames.join(',')) + `</div>
<div id="gender-output" style="display:none;">` + currentGender + `</div>

<script>
var TYPE_LABEL = { novel:'小说', audio:'听书', comic:'漫画', video:'视频' };

function switchTab(t){
    document.querySelectorAll('.tab-btn').forEach(function(b){
        b.classList.toggle('active', b.getAttribute('data-tab') == t);
    });
    document.querySelectorAll('.panel').forEach(function(p){
        p.classList.toggle('active', p.id == 'panel-' + t);
    });
}

function pickGender(g){
    document.querySelectorAll('.gender-btn').forEach(function(b){
        b.classList.toggle('active', b.getAttribute('data-gender') == g);
    });
    document.getElementById('gender-output').textContent = g;
}

function pick(el){
    var isAll = el.getAttribute('data-all') == '1';
    if (isAll) {
        if (el.classList.contains('selected')) {
            el.classList.remove('selected');
        } else {
            document.querySelectorAll('.src-card').forEach(function(c){ c.classList.remove('selected'); });
            el.classList.add('selected');
        }
    } else {
        document.querySelectorAll('.all-card').forEach(function(c){ c.classList.remove('selected'); });
        el.classList.toggle('selected');
    }
    updateOutput();
}

function updateOutput(){
    var allSel = document.querySelector('.all-card.selected');
    var valEl = document.getElementById('current-value');
    var cntEl = document.getElementById('current-count');

    if (allSel) {
        var t = allSel.getAttribute('data-type');
        document.getElementById('result-output').textContent = '__ALL__' + t;
        valEl.textContent = TYPE_LABEL[t] + ' · 全部';
        cntEl.textContent = 'ALL';
        return;
    }
    var names = [];
    document.querySelectorAll('.src-card.selected').forEach(function(c){
        var n = c.getAttribute('data-name');
        if (n) names.push(n);
    });
    document.getElementById('result-output').textContent = names.join(',');
    valEl.textContent = names.length ? names.join('、') : '未选择';
    cntEl.textContent = names.length;
}

function clearAll(){
    document.querySelectorAll('.src-card').forEach(function(c){ c.classList.remove('selected'); });
    updateOutput();
}

(function spawnBubbles(){
    var box = document.getElementById('bubbles');
    if (!box) return;
    var count = 18;
    for (var i = 0; i < count; i++) {
        var b = document.createElement('span');
        b.className = 'bubble';
        var size = 10 + Math.random() * 26;
        b.style.width = size + 'px';
        b.style.height = size + 'px';
        b.style.left = (Math.random() * 100) + '%';

        var drift = (Math.random() * 80 - 40).toFixed(1) + 'px';
