body{font-family:-apple-system,'PingFang SC','Microsoft YaHei',sans-serif;background:#f0f2f5;color:#333;padding:12px;max-width:720px;margin:0 auto}
.container{background:#fff;border-radius:16px;box-shadow:0 4px 24px rgba(0,0,0,0.06);overflow:hidden}
.header{background:linear-gradient(135deg,#ff6b35,#f7931e);padding:20px 24px;color:#fff}
.header h1{font-size:22px;font-weight:700;display:flex;align-items:center;gap:10px}
.header h1 i{font-size:24px}
.header p{font-size:13px;opacity:0.9;margin-top:4px}
.current-section{background:#f8f9fa;margin:16px 16px 0;padding:12px 16px;border-radius:10px;border:1px solid #e9ecef}
.current-label{font-size:13px;color:#868e96;font-weight:500;margin-bottom:4px}
.current-value{font-size:16px;font-weight:600;color:#212529;display:flex;justify-content:space-between;align-items:center}
.current-value .source-tag{font-size:12px;font-weight:400;color:#868e96}
.tabs{display:flex;border-bottom:2px solid #e9ecef;padding:0 16px;margin-top:12px;gap:0}
.tab-btn{padding:12px 20px;border:none;background:transparent;font-size:14px;font-weight:600;color:#868e96;cursor:pointer;border-bottom:3px solid transparent;transition:all 0.2s;display:flex;align-items:center;gap:8px}
.tab-btn i{font-size:16px}
.tab-btn.active{color:#ff6b35;border-bottom-color:#ff6b35}
.tab-btn:hover{color:#ff6b35}
.tab-panel{display:none;padding:16px}
.tab-panel.active{display:block}
.tab-panel .panel-title{font-size:13px;color:#868e96;margin-bottom:12px;padding-left:4px}
.tone-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.tone-btn{padding:12px 8px;border:2px solid #e9ecef;border-radius:12px;background:#fff;cursor:pointer;transition:all 0.2s;text-align:center;font-size:13px;font-weight:500;color:#495057}
.tone-btn:hover{border-color:#ff6b35;transform:translateY(-2px);box-shadow:0 4px 12px rgba(255,107,53,0.15)}
.tone-btn.selected{background:#ff6b35;border-color:#ff6b35;color:#fff;box-shadow:0 4px 12px rgba(255,107,53,0.25)}
.clear-area{padding:0 16px 16px}
.clear-btn{width:100%;padding:12px;border:2px dashed #dee2e6;border-radius:12px;background:transparent;font-size:14px;color:#868e96;cursor:pointer;transition:all 0.2s;display:flex;align-items:center;justify-content:center;gap:8px}
.clear-btn:hover{border-color:#ff6b35;color:#ff6b35;background:#fff5f0}
.action-hint{text-align:center;font-size:12px;color:#adb5bd;padding:12px 16px 16px;border-top:1px solid #f1f3f5}
.action-hint i{color:#ff6b35}
@media (max-width:480px){.tone-grid{grid-template-columns:repeat(3,1fr)}.tab-btn{padding:10px 14px;font-size:13px}}
</style>
</head>
<body>
<div class="container">
<div class="header">
<h1><i class="fas fa-headphones"></i> TTS音色选择</h1>
<p>番茄和书旗音色独立设置，切换Tab分别选择</p>
</div>
<div class="current-section">
<div class="current-label"><i class="fas fa-check-circle" style="color:#40c057;margin-right:6px"></i>当前音色</div>
<div class="current-value">
<span id="fanqie-display">🍅 <span id="fanqie-value">` + fanqieDisplay + `</span></span>
<span id="shuqi-display">📚 <span id="shuqi-value">` + shuqiDisplay + `</span></span>
</div>
</div>
<div class="tabs">
<button class="tab-btn active" data-tab="fanqie" onclick="switchTab('fanqie')"><i class="fas fa-tomato"></i> 番茄</button>
<button class="tab-btn" data-tab="shuqi" onclick="switchTab('shuqi')"><i class="fas fa-book"></i> 书旗</button>
</div>
<div id="panel-fanqie" class="tab-panel active">
<div class="panel-title"><i class="fas fa-list-ul" style="color:#ff6b35"></i> 番茄音色列表</div>
<div class="tone-grid">` + fanqieHtml + `</div>
</div>
<div id="panel-shuqi" class="tab-panel">
<div class="panel-title"><i class="fas fa-list-ul" style="color:#1976d2"></i> 书旗音色列表</div>
<div class="tone-grid">` + shuqiHtml + `</div>
</div>
<div class="clear-area">
<button onclick="clearAll()" class="clear-btn"><i class="fas fa-trash-alt"></i> 清除所有音色</button>
</div>
<div class="action-hint"><i class="fas fa-check-circle"></i> 选择完成后点击右上角 <strong>✓</strong> 确认</div>
</div>
<script>
var fanqieTone = '` + currentFanqieTone + `';
var shuqiTone = '` + currentShuqiTone + `';
var activeTab = '` + activeTab + `';
var fanqieMap = {};
var shuqiMap = {};
var fanqieList = ` + JSON.stringify(fanqieTones) + `;
var shuqiList = ` + JSON.stringify(shuqiTones) + `;
for (var i = 0; i < fanqieList.length; i++) { fanqieMap[fanqieList[i].id] = fanqieList[i].name; }
for (var i = 0; i < shuqiList.length; i++) { shuqiMap[shuqiList[i].id] = shuqiList[i].name; }

function switchTab(tab) {
    activeTab = tab;
    document.querySelectorAll('.tab-btn').forEach(function(b) { b.classList.remove('active'); });
    document.querySelector('.tab-btn[data-tab="' + tab + '"]').classList.add('active');
    document.querySelectorAll('.tab-panel').forEach(function(p) { p.classList.remove('active'); });
    document.getElementById('panel-' + tab).classList.add('active');
}

function selectTone(id, source) {
    if (source == 'fanqie') {
        fanqieTone = id;
        document.querySelectorAll('#panel-fanqie .tone-btn').forEach(function(b) {
            b.classList.remove('selected');
            if (b.getAttribute('data-id') == id) { b.classList.add('selected'); }
        });
        document.getElementById('fanqie-value').textContent = fanqieMap[id] || id;
    } else {
        shuqiTone = id;
        document.querySelectorAll('#panel-shuqi .tone-btn').forEach(function(b) {
            b.classList.remove('selected');
            if (b.getAttribute('data-id') == id) { b.classList.add('selected'); }
        });
        document.getElementById('shuqi-value').textContent = shuqiMap[id] || id;
    }
}

function clearAll() {
    fanqieTone = '';
    shuqiTone = '';
    document.querySelectorAll('.tone-btn').forEach(function(b) { b.classList.remove('selected'); });
    document.getElementById('fanqie-value').textContent = '未选择';
    document.getElementById('shuqi-value').textContent = '未选择';
}
</script>
</body>
