@js:
let isAndroid = deviceType();
let title = chapter.title || "";

if (isAndroid) {
    let chapterParams = JSON.parse(java.hexDecodeToString(result));

    let bookid = chapterParams.bookid || null;
    let chapterid = chapterParams.chapterid || null;

    let yunparaStatus = java.get("yunpara") || "off";

    let isModifiedVersion = checkEnv();
    let isQingRead = isQRead();

    let isQQSource = chapterParams.source == 'QQ阅读' || chapterParams.source == '企鹅看书';
    let isQDSource = chapterParams.source == '起点';

    if ((isModifiedVersion || isQingRead) && yunparaStatus == "on" && bookid && chapterid) {
        if (isQQSource || isQDSource) {
            let Bubble = cache.get(bookid + "_" + chapterid) || "";
            title = title + Bubble;
        }
    }
}
title;

