source.exploreUrl:
@js:
res = []
//书架
user = java.t2s(java.ajax("https://tw.linovelib.com/user.php"))
if (user.match(/<title>登入 - 哔哩轻小说<\/title>/gi)) {
  //未登录
  res.push(
    {
      title: `>> 我的书架 | 未登录 <<`,
      url: '',
      style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
    })
} else {
  //已登录
  res.push(
    {
      title: `>> 我的书架 | ${user.match(/<span class="user-name">.+<\/span>/gi)[0].replace(/<\/?span.*?>/gi,'')} <<`,
      url: '',
      style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
    })
  bookcase = java.t2s(java.ajax("https://tw.linovelib.com/bookcase.php"))
  bookcase.match(/<select[\s\S]+?<\/select>/gi)[0].match(/<option.+<\/option>/gi).forEach(option => {
    res.push(
      {
        title: option.match(/>.+(?=<)/gi)[0].replace('>', ''),
        url: "https://tw.linovelib.com/bookcase.php?classid=" + option.match(/value=\".+?(?=\")/gi)[0].replace(/(value=\")/gi, ''),
        style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
      })
  })
}

content = java.t2s(java.ajax("https://tw.linovelib.com/wenku/"))
content.match(/排序方式[\s\S]+?<\/div>/gi)[0].match(/<a.+<\/a>/gi).forEach(a => {
  let sortTitle = a.match(/>.+(?=<)/gi)[0].replace('>', '')
  let sortAddress = a.match(/\/.+?(?=_)/gi)[0].replace('/', '')
  content.match(/作品分类[\s\S]+?<\/div>/gi)[0].match(/<a.+<\/a>/gi).forEach((v, i) => {
    if (i == 0) {
      res.push(
        {
          title: `>> 全部文库 | ${sortTitle} <<`,
          url: v.match(/href=\".+?(?=\")/gi)[0].replace(/(href=\")/gi, '')
            .replace(/\/.+?(?=_)/gi, '/' + sortAddress).replace('1_0.html', '{{page}}_0.html'),
          style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
        })
    } else {
      res.push(
        {
          title: v.match(/>.+(?=<)/gi)[0].replace('>', ''),
          url: v.match(/href=\".+?(?=\")/gi)[0].replace(/(href=\")/gi, '')
            .replace(/\/.+?(?=_)/gi, '/' + sortAddress).replace('1_0.html', '{{page}}_0.html'),
          style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
        })
    }
  })
})
content.match(/排序方式[\s\S]+?重置/gi)[0].match(/<li[\s\S]+?<\/li>/gi).forEach(li => {
  let sortTitle = li.match(/>.+(?=<\/h3>)/gi)[0].replace('>', '')
  res.push(
    {
      title: `>> ${sortTitle} <<`,
      url: '',
      style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
    })
  li.match(/<a.+<\/a>/gi).forEach((v, i) => {
    if (i != 0) {
      res.push(
        {
          title: v.match(/>.+(?=<)/gi)[0].replace('>', ''),
          url: v.match(/href=\".+?(?=\")/gi)[0].replace(/(href=\")/gi, '').replace('1_0.html', '{{page}}_0.html'),
          style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
        })
    }
  })
})
tagContent = java.t2s(java.ajax("https://tw.linovelib.com/taglist/1.html"))
res.push(
  {
    title: '>> 标签分类 <<',
    url: '',
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
  })
tagContent.match(/标签分类<\/h3>[\s\S]+?重置/gi)[0].match(/<a.+<\/a>/gi).forEach((v, i) => {
  res.push(
    {
      title: v.match(/>.+(?=<)/gi)[0].replace('>', ''),
      url: v.match(/href=\".+?(?=\")/gi)[0].replace(/(href=\")/gi, '').replace('1.html', '{{page}}.html'),
      style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
    })
})
JSON.stringify(res)

