ruleContent.content:
$.content
<js>
let content = result;
let device, device_type;
try {
    device = java.androidId();
    device_type = '安卓';
} catch (e) {
    try {
        device = java.deviceID();
        device_type = '苹果';
    } catch (e) {
        device = '';
        device_type = '安卓';
    }
}
if (device_type=='安卓') {
	data = {'content':`【右上角刷新】开启播放(下一集请切换下一章刷新)\n播放直链：${content}`}
	data = JSON.stringify(data);
	 if (book.durChapterIndex===chapter.index){
	 	java.toast(chapter.title);
	 let 	book_id = java.get('book_id');
	 let sources = java.get('sources');
		let video_url = `https://v1.gyks.cf/online_video?book_id=${book_id}&source=${sources}&tab=短剧`;
		if (sources.includes('毒舌影视') || sources.includes('NT动漫')) {
			video_url = content;
			}
  	java.startBrowser(video_url,'短剧');
	 	java.toast('正在加载视频...');
	};
	} else {
		data = {'content':content}
	data = JSON.stringify(data);
		}
data;
</js>
$.content

